const emojiRecords = emojiData
  .slice(0, -RECORD_SEPARATOR.length)
  .split(RECORD_SEPARATOR);
const emojiByTag = new Map<string, string>(
  emojiRecords.map<[string, string]>((record) => {
    const separator = record.indexOf(FIELD_SEPARATOR);
    return [
      record.slice(0, separator),
      record.slice(separator + FIELD_SEPARATOR.length),
    ];
  }),
);
const emojiValues = new Set<string>(emojiByTag.values());

export interface NtfyEmojiTag {
  tag: string;
  emoji: string;
}

export interface NtfyTagPresentation {
  emojiTags: NtfyEmojiTag[];
  textTags: string[];
}

export function ntfyEmojiForTag(tag: string): string | null {
  return emojiByTag.get(tag) ?? (emojiValues.has(tag) ? tag : null);
}

export function presentNtfyTags(tags: readonly string[]): NtfyTagPresentation {
  const emojiTags: NtfyEmojiTag[] = [];
  const textTags: string[] = [];

  for (const tag of tags) {
    const emoji = ntfyEmojiForTag(tag);
    if (emoji) emojiTags.push({ tag, emoji });
    else textTags.push(tag);
  }

  return { emojiTags, textTags };
}
